;\n}\n\nexport interface Application extends BaseRecord {\n  company: string;\n  position: string;\n  jobType: \"graduate\" | \"internship\" | \"tech\" | \"general\" | \"other\";\n  location: string;\n  workMode: \"onsite\" | \"remote\" | \"hybrid\" | \"unknown\";\n  salaryText: string;\n  source: string;\n  jobUrl: string;\n  jdText: string;\n  jdFileId?: string;\n  currentResumeId?: string;\n  stageId: string;\n  priority: number;\n  deadline?: string;\n  contact: string;\n  note: string;\n  archivedAt?: string;\n}\n\nexport interface ResumeUsageHistory extends BaseRecord {\n  applicationId: string;\n  resumeId: string;\n  resumeNameSnapshot: string;\n  textSnapshot: string;\n  usedAt: string;\n}\n\nexport interface Stage extends BaseRecord {\n  name: string;\n  color: string;\n  order: number;\n  kind: StageKind;\n}\n\nexport type TimelineEventType =\n  | \"stage-changed\"\n  | \"resume-changed\"\n  | \"note-added\"\n  | \"archived\"\n  | \"interview-rescheduled\";\n\nexport interface ApplicationTimelineEvent extends BaseRecord {\n  applicationId: string;\n  type: TimelineEventType;\n  fromValue?: string;\n  toValue?: string;\n  note: string;\n}\n\nexport interface Reminder {\n  offsetMinutes: number;\n  channel: \"in-app\" | \"browser\";\n}\n\nexport interface Interview extends BaseRecord {\n  applicationId: string;\n  round: number;\n  type: \"phone\" | \"video\" | \"onsite\" | \"assessment\" | \"other\";\n  title: string;\n  startsAt: string;\n  endsAt?: string;\n  timezone: string;\n  locationOrLink: string;\n  interviewer: string;\n  status: InterviewStatus;\n  reminders: Reminder[];\n  calendarExportedAt?: string;\n  note: string;\n}\n\nexport interface ReviewQuestion {\n  question: string;\n  answer?: string;\n  note?: string;\n}\n\nexport interface InterviewReview extends BaseRecord {\n  interviewId: string;\n  overallRating?: number;\n  questions: ReviewQuestion[];\n  goodAnswers: string;\n  weakAnswers: string;\n  observedSignals: string;\n  salaryDiscussion: string;\n  nextStep: string;\n  privateNote: string;\n}\n\nexport interface ReminderFailure extends BaseRecord {\n  interviewId: string;\n  reminderAt: string;\n  reason: string;\n}\n\nexport interface AnalysisCoverage {\n  overall: number;\n  required: number;\n  preferred: number;\n}\n\nexport interface AnalysisEvidence {\n  keyword: string;\n  excerpt: string;\n}\n\nexport interface AnalysisResult extends BaseRecord {\n  applicationId: string;\n  resumeId: string;\n  mode: \"local\" | \"ai\";\n  coverage: AnalysisCoverage;\n  matchedKeywords: string[];\n  weakMatches: string[];\n  missingKeywords: string[];\n  evidence: AnalysisEvidence[];\n  uncertainItems: string[];\n  recommendations: string[];\n}\n\nexport interface AiMessage {\n  id: string;\n  role: \"system\" | \"user\" | \"assistant\";\n  content: string;\n  createdAt: string;\n}\n\nexport interface AiConversation extends BaseRecord {\n  applicationId: string;\n  messages: AiMessage[];\n}\n\nexport interface StoredFile extends BaseRecord {\n  ownerType: \"resume\" | \"job-description\";\n  ownerId: string;\n  fileName: string;\n  fileType: \"pdf\" | \"docx\";\n  blob: Blob;\n}\n\nexport interface SensitiveSettingsRecord extends BaseRecord {\n  id: \"ai\";\n  apiUrl: string;\n  model: string;\n  apiKey: string;\n  organizationId: string;\n  customHeaders: Record<string, string>;\n}\n\nexport interface DomainRecordMap {\n  resumes: Resume;\n  resumeTexts: ResumeText;\n  jobDescriptions: JobDescription;\n  jobDescriptionTexts: JobDescriptionText;\n  applications: Application;\n  resumeUsageHistory: ResumeUsageHistory;\n  stages: Stage;\n  applicationTimelineEvents: ApplicationTimelineEvent;\n  interviews: Interview;\n  interviewReviews: InterviewReview;\n  analysisResults: AnalysisResult;\n  aiConversations: AiConversation;\n  reminderFailures: ReminderFailure;\n  originalFiles: StoredFile;\n}\n\nexport type DomainStoreName = keyof DomainRecordMap;\nexport const DATABASE_NAME = \"local-career-workspace\";\nexport const DATABASE_VERSION = 6;\n\nexport const STORE_NAMES = {\n  resumes: \"resumes\",\n  resumeTexts: \"resumeTexts\",\n  jobDescriptions: \"jobDescriptions\",\n  jobDescriptionTexts: \"jobDescriptionTexts\",\n  applications: \"applications\",\n  resumeUsageHistory: \"resumeUsageHistory\",\n  stages: \"stages\",\n  applicationTimelineEvents: \"applicationTimelineEvents\",\n  interviews: \"interviews\",\n  interviewReviews: \"interviewReviews\",\n  analysisResults: \"analysisResults\",\n  aiConversations: \"aiConversations\",\n  reminderFailures: \"reminderFailures\",\n  originalFiles: \"originalFiles\",\n  sensitiveSettings: \"sensitiveSettings\",\n} as const;\n\nexport type StoreName = (typeof STORE_NAMES)[keyof typeof STORE_NAMES];\n\ninterface IndexDefinition {\n  name: string;\n  keyPath: string | string[];\n  unique?: boolean;\n}\n\nconst INDEXES: Record<StoreName, readonly IndexDefinition[]> = {\n  resumes: [\n    { name: \"status\", keyPath: \"status\" },\n    { name: \"fileHash\", keyPath: \"fileHash\" },\n    { name: \"updatedAt\", keyPath: \"updatedAt\" },\n  ],\n  resumeTexts: [\n    { name: \"resumeId\", keyPath: \"resumeId\" },\n    { name: \"resumeId_kind\", keyPath: [\"resumeId\", \"kind\"], unique: true },\n  ],\n  jobDescriptions: [\n    { name: \"applicationId\", keyPath: \"applicationId\" },\n    { name: \"fileHash\", keyPath: \"fileHash\" },\n  ],\n  jobDescriptionTexts: [\n    { name: \"jobDescriptionId\", keyPath: \"jobDescriptionId\" },\n    {\n      name: \"jobDescriptionId_kind\",\n      keyPath: [\"jobDescriptionId\", \"kind\"],\n      unique: true,\n    },\n  ],\n  applications: [\n    { name: \"stageId\", keyPath: \"stageId\" },\n    { name: \"currentResumeId\", keyPath: \"currentResumeId\" },\n    { name: \"updatedAt\", keyPath: \"updatedAt\" },\n  ],\n  resumeUsageHistory: [\n    { name: \"applicationId\", keyPath: \"applicationId\" },\n    { name: \"resumeId\", keyPath: \"resumeId\" },\n  ],\n  stages: [\n    { name: \"kind\", keyPath: \"kind\" },\n    { name: \"order\", keyPath: \"order\" },\n  ],\n  applicationTimelineEvents: [\n    { name: \"applicationId\", keyPath: \"applicationId\" },\n    { name: \"createdAt\", keyPath: \"createdAt\" },\n  ],\n  interviews: [\n    { name: \"applicationId\", keyPath: \"applicationId\" },\n    { name: \"startsAt\", keyPath: \"startsAt\" },\n    { name: \"status\", keyPath: \"status\" },\n  ],\n  interviewReviews: [\n    { name: \"interviewId\", keyPath: \"interviewId\", unique: true },\n  ],\n  analysisResults: [\n    { name: \"applicationId\", keyPath: \"applicationId\" },\n    { name: \"resumeId\", keyPath: \"resumeId\" },\n    { name: \"createdAt\", keyPath: \"createdAt\" },\n  ],\n  aiConversations: [{ name: \"applicationId\", keyPath: \"applicationId\" }],\n  reminderFailures: [\n    { name: \"interviewId\", keyPath: \"interviewId\" },\n    { name: \"reminderAt\", keyPath: \"reminderAt\" },\n  ],\n  originalFiles: [\n    { name: \"ownerId\", keyPath: \"ownerId\" },\n    {\n      name: \"ownerType_ownerId\",\n      keyPath: [\"ownerType\", \"ownerId\"],\n      unique: true,\n    },\n  ],\n  sensitiveSettings: [],\n};\n\nexport function ensureSchema(\n  database: IDBDatabase,\n  transaction: IDBTransaction,\n): void {\n  for (const storeName of Object.values(STORE_NAMES)) {\n    const store = database.objectStoreNames.contains(storeName)\n      ? transaction.objectStore(storeName)\n      : database.createObjectStore(storeName, { keyPath: \"id\" });\n\n    for (const index of INDEXES[storeName]) {\n      if (!store.indexNames.contains(index.name)) {\n        store.createIndex(index.name, index.keyPath, {\n          unique: index.unique ?? false,\n        });\n      }\n    }\n  }\n}\nimport {\n  DATABASE_NAME,\n  DATABASE_VERSION,\n  ensureSchema,\n  type StoreName,\n} from \"./schema\";\nimport { runMigrations } from \"./migrations\";\n\nexport interface OpenDatabaseOptions {\n  name?: string;\n  version?: number;\n  factory?: IDBFactory;\n}\n\nexport function requestToPromise<T>(request: IDBRequest<T>): Promise<T> {\n  return new Promise((resolve, reject) => {\n    request.addEventListener(\"success\", () => resolve(request.result));\n    request.addEventListener(\"error\", () =>\n      reject(request.error ?? new Error(\"IndexedDB request failed\")),\n    );\n  });\n}\n\nexport function transactionToPromise(transaction: IDBTransaction): Promise<void> {\n  return new Promise((resolve, reject) => {\n    transaction.addEventListener(\"complete\", () => resolve());\n    transaction.addEventListener(\"abort\", () =>\n      reject(transaction.error ?? new Error(\"IndexedDB transaction aborted\")),\n    );\n    transaction.addEventListener(\"error\", () =>\n      reject(transaction.error ?? new Error(\"IndexedDB transaction failed\")),\n    );\n  });\n}\n\nexport async function runTransaction<T>(\n  database: IDBDatabase,\n  storeNames: StoreName | readonly StoreName[],\n  mode: IDBTransactionMode,\n  operation: (transaction: IDBTransaction) => T | Promise<T>,\n): Promise<T> {\n  const transaction = database.transaction(storeNames, mode);\n  const completion = transactionToPromise(transaction);\n\n  try {\n    const result = await operation(transaction);\n    await completion;\n    return result;\n  } catch (error) {\n    try {\n      transaction.abort();\n    } catch {\n      // The transaction may already have completed or aborted.\n    }\n    await completion.catch(() => undefined);\n    throw error;\n  }\n}\n\nexport function openCareerDatabase(\n  options: OpenDatabaseOptions = {},\n): Promise<IDBDatabase> {\n  const factory = options.factory ?? indexedDB;\n  const name = options.name ?? DATABASE_NAME;\n  const version = options.version ?? DATABASE_VERSION;\n\n  return new Promise((resolve, reject) => {\n    const request = factory.open(name, version);\n    let upgradeError: unknown;\n\n    request.addEventListener(\"upgradeneeded\", (event) => {\n      try {\n        const transaction = request.transaction;\n        if (!transaction) {\n          throw new Error(\"IndexedDB upgrade transaction is unavailable\");\n        }\n        ensureSchema(request.result, transaction);\n        runMigrations(transaction, event.oldVersion, (error) => {\n          if (upgradeError === undefined) {\n            upgradeError = error;\n          }\n        });\n      } catch (error) {\n        upgradeError = error;\n        request.transaction?.abort();\n      }\n    });\n    request.addEventListener(\"success\", () => resolve(request.result));\n    request.addEventListener(\"error\", () =>\n      reject(\n        upgradeError ?? request.error ?? new Error(\"Unable to open IndexedDB\"),\n      ),\n    );\n    request.addEventListener(\"blocked\", () =>\n      reject(new Error(`IndexedDB upgrade is blocked for ${name}`)),\n    );\n  });\n}\n\nexport function deleteCareerDatabase(\n  name = DATABASE_NAME,\n  factory: IDBFactory = indexedDB,\n): Promise<void> {\n  return new Promise((resolve, reject) => {\n    const request = factory.deleteDatabase(name);\n    request.addEventListener(\"success\", () => resolve());\n    request.addEventListener(\"error\", () =>\n      reject(request.error ?? new Error(`Unable to delete IndexedDB ${name}`)),\n    );\n    request.addEventListener(\"blocked\", () =>\n      reject(new Error(`IndexedDB deletion is blocked for ${name}`)),\n    );\n  });\n}\n\nexport const openDatabase = openCareerDatabase;\n","exit_code":0,"status":"completed"}}
