{"type":"item.completed","item":{"id":"item_30","type":"command_execution","command":"/bin/bash -lc \"sed -n '1,240p' src/storage/dataManagement.ts; sed -n '1,180p' tests/storage/dataManagement.test.ts\"","aggregated_output":"import { requestToPromise, runTransaction } from \"../db/database\";\nimport { STORE_NAMES, type StoreName } from \"../db/schema\";\n\nexport interface DataClearPreview {\n  recordCounts: Record<StoreName, number>;\n  totalRecords: number;\n  structuredRecords: number;\n  textRecords: number;\n  texts: number;\n  blobs: number;\n  blobRecords: number;\n}\n\nexport interface ClearAllOptions {\n  confirmed?: boolean;\n  confirmationWord?: string;\n}\n\nexport interface ClearAllResult {\n  cleared: boolean;\n  error?: Error;\n}\n\nconst ALL_STORES = Object.values(STORE_NAMES) as StoreName[];\nexport const CLEAR_CONFIRMATION_WORD = \"DELETE\";\nconst TEXT_STORES = new Set<StoreName>([\n  STORE_NAMES.resumeTexts,\n  STORE_NAMES.jobDescriptionTexts,\n]);\n\ntype Snapshot = Record<StoreName, unknown[]>;\n\nasync function snapshotData(database: IDBDatabase): Promise<Snapshot> {\n  return runTransaction(database, ALL_STORES, \"readonly\", async (tx) => {\n    const result = {} as Snapshot;\n    await Promise.all(\n      ALL_STORES.map(async (storeName) => {\n        result[storeName] = await requestToPromise<unknown[]>(\n          tx.objectStore(storeName).getAll(),\n        );\n      }),\n    );\n    return result;\n  });\n}\n\nexport async function previewDataClear(database: IDBDatabase): Promise<DataClearPreview> {\n  const snapshot = await snapshotData(database);\n  const recordCounts = {} as Record<StoreName, number>;\n  let totalRecords = 0;\n  let textRecords = 0;\n  let blobs = 0;\n  let structuredRecords = 0;\n  for (const storeName of ALL_STORES) {\n    const count = snapshot[storeName].length;\n    recordCounts[storeName] = count;\n    if (storeName !== STORE_NAMES.sensitiveSettings) totalRecords += count;\n    if (TEXT_STORES.has(storeName)) textRecords += count;\n    if (storeName === STORE_NAMES.originalFiles) blobs = count;\n    if (!TEXT_STORES.has(storeName) && storeName !== STORE_NAMES.originalFiles && storeName !== STORE_NAMES.sensitiveSettings) {\n      structuredRecords += count;\n    }\n  }\n  return {\n    recordCounts,\n    totalRecords,\n    structuredRecords,\n    textRecords,\n    texts: textRecords,\n    blobs,\n    blobRecords: blobs,\n  };\n}\n\nasync function restoreSnapshot(database: IDBDatabase, snapshot: Snapshot): Promise<void> {\n  await runTransaction(database, ALL_STORES, \"readwrite\", (tx) => {\n    const requests: Promise<unknown>[] = [];\n    for (const storeName of ALL_STORES) {\n      const store = tx.objectStore(storeName);\n      requests.push(requestToPromise(store.clear()));\n      for (const record of snapshot[storeName]) {\n        requests.push(requestToPromise(store.put(record)));\n      }\n    }\n    return Promise.all(requests).then(() => undefined);\n  });\n}\n\nexport async function clearAllData(\n  database: IDBDatabase,\n  options: ClearAllOptions = {},\n): Promise<ClearAllResult> {\n  if (!options.confirmed && options.confirmationWord !== CLEAR_CONFIRMATION_WORD) {\n    return { cleared: false };\n  }\n\n  let snapshot: Snapshot;\n  const localStorageSnapshot: Record<string, string> = {};\n  try {\n    snapshot = await snapshotData(database);\n    for (let index = 0; index < localStorage.length; index += 1) {\n      const key = localStorage.key(index);\n      if (key) localStorageSnapshot[key] = localStorage.getItem(key) ?? \"\";\n    }\n  } catch (cause) {\n    return { cleared: false, error: cause instanceof Error ? cause : new Error(String(cause)) };\n  }\n  try {\n    await runTransaction(database, ALL_STORES, \"readwrite\", async (tx) => {\n      await Promise.all(\n        ALL_STORES.map((storeName) =>\n          requestToPromise(tx.objectStore(storeName).clear()),\n        ),\n      );\n    });\n    localStorage.clear();\n    return { cleared: true };\n  } catch (cause) {\n    try {\n      await restoreSnapshot(database, snapshot);\n      localStorage.clear();\n      for (const [key, value] of Object.entries(localStorageSnapshot)) {\n        localStorage.setItem(key, value);\n      }\n    } catch (restoreError) {\n      return { cleared: false, error: restoreError instanceof Error ? restoreError : new Error(String(restoreError)) };\n    }\n    return { cleared: false, error: cause instanceof Error ? cause : new Error(String(cause)) };\n  }\n}\n\nexport const SENSITIVE_SETTINGS_ID = \"ai\";\nexport const getDataClearPreview = previewDataClear;\nexport const clearAllLocalData = clearAllData;\nimport { afterEach, describe, expect, it } from \"vitest\";\n\nimport { deleteCareerDatabase, openCareerDatabase } from \"../../src/db/database\";\nimport { createRepositories } from \"../../src/db/repositories\";\nimport { BlobStore } from \"../../src/storage/blobStore\";\nimport { clearAllData, previewDataClear } from \"../../src/storage/dataManagement\";\nimport { saveAiSettings } from \"../../src/settings/secrets\";\nimport { savePreferences } from \"../../src/settings/preferences\";\n\nconst names = new Set<string>();\nconst dbs = new Set<IDBDatabase>();\n\nafterEach(async () => {\n  dbs.forEach((db) => db.close());\n  dbs.clear();\n  localStorage.clear();\n  await Promise.all([...names].map((name) => deleteCareerDatabase(name)));\n  names.clear();\n});\n\ndescribe(\"data management\", () => {\n  it(\"previews counts and keeps data when confirmation is cancelled\", async () => {\n    const name = `clear-${crypto.randomUUID()}`;\n    names.add(name);\n    const db = await openCareerDatabase({ name });\n    dbs.add(db);\n    const repositories = createRepositories(db);\n    await repositories.resumes.create({\n      name: \"Resume\",\n      type: \"pdf\",\n      fileName: \"resume.pdf\",\n      fileSize: 4,\n      fileHash: \"hash\",\n      uploadedAt: \"2026-09-01T00:00:00.000Z\",\n      tags: [],\n      note: \"\",\n      status: \"ready\",\n    });\n    await repositories.resumeTexts.create({ resumeId: \"r1\", kind: \"confirmed\", text: \"long text\" });\n    await new BlobStore(db).save({ ownerType: \"resume\", ownerId: \"r1\", fileName: \"resume.pdf\", fileType: \"pdf\", blob: new Blob([\"bytes\"], { type: \"application/pdf\" }) });\n    await saveAiSettings(db, { apiUrl: \"https://api.example.test\", model: \"m\", apiKey: \"k\", organizationId: \"\", customHeaders: {} });\n    savePreferences({ defaultTimezone: \"UTC\" });\n\n    const preview = await previewDataClear(db);\n    expect(preview.totalRecords).toBe(3);\n    expect(preview.blobs).toBe(1);\n    expect(await clearAllData(db, { confirmed: false })).toEqual({ cleared: false });\n    expect((await repositories.resumes.list())).toHaveLength(1);\n    expect(localStorage.length).toBeGreaterThan(0);\n  });\n\n  it(\"clears every store and local settings after confirmation\", async () => {\n    const name = `clear-confirm-${crypto.randomUUID()}`;\n    names.add(name);\n    const db = await openCareerDatabase({ name });\n    dbs.add(db);\n    const repositories = createRepositories(db);\n    await repositories.stages.create({ name: \"Applied\", color: \"#000\", order: 1, kind: \"normal\" });\n    await saveAiSettings(db, { apiUrl: \"https://api.example.test\", model: \"m\", apiKey: \"k\", organizationId: \"\", customHeaders: {} });\n    savePreferences({ defaultTimezone: \"UTC\" });\n    await expect(clearAllData(db, { confirmationWord: \"DELETE\" })).resolves.toEqual({ cleared: true });\n    expect(await repositories.stages.list()).toEqual([]);\n    expect(localStorage.length).toBe(0);\n  });\n\n  it(\"returns an error and leaves local settings untouched when the database is unavailable\", async () => {\n    const name = `clear-failure-${crypto.randomUUID()}`;\n    names.add(name);\n    const db = await openCareerDatabase({ name });\n    dbs.add(db);\n    savePreferences({ defaultTimezone: \"UTC\" });\n    db.close();\n\n    const result = await clearAllData(db, { confirmed: true });\n    expect(result.cleared).toBe(false);\n    expect(result.error).toBeInstanceOf(Error);\n    expect(localStorage.length).toBeGreaterThan(0);\n  });\n});\n","exit_code":0,"status":"completed"}}
